    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.abstractCanCommunicationControllerAttributesEClass, source, new String[]{"documentation", "For the configuration of the CanController parameters two different approaches can be used:\r\n1. Providing exact values which are taken by the ECU developer (CanControllerConfiguration).\r\n2. Providing ranges of values which are taken as requirements and have to be respected by the ECU developer (CanControllerConfigurationRequirements)."});
        this.addAnnotation((ENamedElement)this.canClusterEClass, source, new String[]{"documentation", "CAN specific attributes"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmBusLoadReductionActive(), source, new String[]{"documentation", "It determines if bus load reduction for the respective NM channel is active or not. \r\nTrue: active\r\nFalse: inactive"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmBusLoadReductionEnabled(), source, new String[]{"documentation", "switch for enabling busload reduction support."});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmImmediateNmCycleTime(), source, new String[]{"documentation", "Defines the immediate NM PDU cycle time in seconds which is used for nmImmediateNmTransmissions NM PDU transmissions. This parameter is only valid if CanNmImmediateNmTransmissions is greater one.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmImmediateNmTransmissions(), source, new String[]{"documentation", "Defines the number of immediate NM PDUs which shall be transmitted. If the value is zero no immediate NM PDUs are transmitted. The cycle time of immeditate NM PDUs is defined by nmImmediateNmCycleTime.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmImmediateRestartEnabled(), source, new String[]{"documentation", "Enables the asynchronous transmission of a CanNm PDU upon bus-communication request in Prepare-Bus-Sleep mode.\r\n\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmLowerCanId(), source, new String[]{"documentation", "This attribute can be used together with the nmUpperCanId attribute to define a range of CanIds. Can Frames which will arrive in the given Id Range will be handled as Nm Pdus. \r\n\r\nThis range definition is redundant to the attribute \"rxIdentifierRange\" of \"CanFrameTriggering\". For backward compatibility reasons this redundancy shall be preserved and both shall be defined.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmMsgCycleTime(), source, new String[]{"documentation", "Period of a CanNm message in seconds. It determines the periodic rate in the periodic transmission mode with bus load reduction and is the basis for transmit scheduling in the periodic transmission mode without bus load reduction.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmRemoteSleepIndicationTime(), source, new String[]{"documentation", "Timeout for Remote Sleep Indication in seconds. It defines the time how long it shall take to recognize that all other nodes are ready to sleep.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmRepeatMessageStateTime(), source, new String[]{"documentation", "It defines how long the NM shall stay in the Repeat Message State (in seconds)"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmTimeoutTime(), source, new String[]{"documentation", "Network Timeout for NM-Messages. It denotes the time (in seconds) how long the NM shall stay in the Network Mode before transition into Prepare Bus-Sleep Mode shall take place. It shall be equal for all nodes in the cluster."});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmUpperCanId(), source, new String[]{"documentation", "This attribute can be used together with the nmLowerCanId attribute to define a range of CanIds. Can Frames which will arrive in the given Id Range will be handled as Nm Pdus. \r\n\r\nThis range definition is redundant to the attribute \"rxIdentifierRange\" of \"CanFrameTriggering\". For backward compatibility reasons this redundancy shall be preserved and both shall be defined.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCluster_NmWaitBusSleepTime(), source, new String[]{"documentation", "Timeout for bus calm down phase. It denotes the time (in seconds) how long the NM shall stay in the Prepare Bus-Sleep Mode before transition into Bus-Sleep Mode shall take place. It shall be equal for all nodes in the cluster. "});
        this.addAnnotation((ENamedElement)this.canCommunicationConnectorEClass, source, new String[]{"documentation", "CAN bus specific communication connector attributes."});
        this.addAnnotation((ENamedElement)this.getCanCommunicationConnector_PncWakeupCanId(), source, new String[]{"documentation", "CAN Identifier used to configure the CAN Transceiver for partial network wakeup.  "});
        this.addAnnotation((ENamedElement)this.getCanCommunicationConnector_PncWakeupCanIdExtended(), source, new String[]{"documentation", "Defines whether pncWakeupCanId and pncWakeupCanIdMask shall be interpreted as extended or standard CAN ID.\r\ntrue: extended Can identifier is used\r\nfalse: standard Can identifier is used\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCommunicationConnector_PncWakeupCanIdMask(), source, new String[]{"documentation", "Bit mask for CAN Identifier used to configure the CAN Transceiver for partial network wakeup.  "});
        this.addAnnotation((ENamedElement)this.getCanCommunicationConnector_PncWakeupDataMask(), source, new String[]{"documentation", "Bit mask for CAN Payload used to configure the CAN Transceiver for partial network wakeup.  "});
        this.addAnnotation((ENamedElement)this.getCanCommunicationConnector_PncWakeupDlc(), source, new String[]{"documentation", "Data Length of the remote data frame used to configure the CAN Transceiver for partial network wakeup in Bytes.\r\n"});
        this.addAnnotation((ENamedElement)this.canCommunicationControllerEClass, source, new String[]{"documentation", "CAN bus specific communication port attributes."});
        this.addAnnotation((ENamedElement)this.getCanCommunicationController_CanControllerAttributes(), source, new String[]{"documentation", "CAN Bit Timing configuration"});
        this.addAnnotation((ENamedElement)this.getCanCommunicationController_NmMsgCycleOffset(), source, new String[]{"documentation", "Node specific time offset in the periodic transmission node. It determines the start delay of the transmission. Specified in seconds.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCommunicationController_NmMsgReducedTime(), source, new String[]{"documentation", "Node specific bus cycle time in the periodic transmission mode with bus load reduction. Specified in seconds.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanCommunicationController_NmUserDataEnabled(), source, new String[]{"documentation", "Switch for enabling user data support.\r\n"});
        this.addAnnotation((ENamedElement)this.canControllerConfigurationEClass, source, new String[]{"documentation", "This element is used for the specification of the exact CAN Bit Timing configuration parameter values. "});
        this.addAnnotation((ENamedElement)this.getCanControllerConfiguration_NumberOfSamples(), source, new String[]{"documentation", "Number of samples. Possible values are 1 or 3."});
        this.addAnnotation((ENamedElement)this.getCanControllerConfiguration_PropagationDelay(), source, new String[]{"documentation", "The propagation time segment in quanta."});
        this.addAnnotation((ENamedElement)this.getCanControllerConfiguration_SyncJumpWidth(), source, new String[]{"documentation", "The number of quanta in the Synchronization Jump Width, SJW. The (Re-)Synchronization Jump Width (SJW) defines how far a resynchronization may move the Sample Point inside the limits defined by the Phase Buffer Segments to compensate for edge phase errors."});
        this.addAnnotation((ENamedElement)this.getCanControllerConfiguration_TimeSeg1(), source, new String[]{"documentation", "The number of quanta before the sampling point.\r\n\r\nThe propagation time segment is factored into the timeSeg1 configuration parameter:\r\ntimeSeg1 = tPROP_SEG + tPHASE_SEG1"});
        this.addAnnotation((ENamedElement)this.getCanControllerConfiguration_TimeSeg2(), source, new String[]{"documentation", "The number of quanta after the sampling point:\r\ntimeSeg2 = Phase_Seg2"});
        this.addAnnotation((ENamedElement)this.canControllerConfigurationRequirementsEClass, source, new String[]{"documentation", "This element allows the specification of ranges for the CAN Bit Timing configuration parameters. These ranges are taken as requirements and have to be respected by the ECU developer."});
        this.addAnnotation((ENamedElement)this.getCanControllerConfigurationRequirements_MaxNumberOfTimeQuantaPerBit(), source, new String[]{"documentation", "Maximum number of time quanta in the bit time."});
        this.addAnnotation((ENamedElement)this.getCanControllerConfigurationRequirements_MaxSamplePoint(), source, new String[]{"documentation", "The max. value of the sample point as a percentage of the total bit time. "});
        this.addAnnotation((ENamedElement)this.getCanControllerConfigurationRequirements_MaxSyncJumpWidth(), source, new String[]{"documentation", "The max. Synchronization Jump Width value as a percentage of the total bit time. The (Re-)Synchronization Jump Width (SJW) defines how far a resynchronization may move the Sample Point inside the limits defined by the Phase Buffer Segments to compensate for edge phase errors."});
        this.addAnnotation((ENamedElement)this.getCanControllerConfigurationRequirements_MinNumberOfTimeQuantaPerBit(), source, new String[]{"documentation", "Minimum number of time quanta in the bit time."});
        this.addAnnotation((ENamedElement)this.getCanControllerConfigurationRequirements_MinSamplePoint(), source, new String[]{"documentation", "The min. value of the sample point as a percentage of the total bit time. "});
        this.addAnnotation((ENamedElement)this.getCanControllerConfigurationRequirements_MinSyncJumpWidth(), source, new String[]{"documentation", "The min. Synchronization Jump Width value as a percentage of the total bit time. The (Re-)Synchronization Jump Width (SJW) defines how far a resynchronization may move the Sample Point inside the limits defined by the Phase Buffer Segments to compensate for edge phase errors."});
    }

